import{_ as e,C as t,c as i,o as a,a0 as r,b as s,w as n,a as o,G as l,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Atelier : Séance avancée de préparation mentale (3-4 heures)","description":"","frontmatter":{},"headers":[],"relativePath":"fr/workshop.md","filePath":"fr/workshop.md"}');const p=e({name:"fr/workshop.md"},[["render",function(e,c,p,d,m,h){const g=t("Mermaid");return a(),i("div",null,[c[4]||(c[4]=r('<h1 id="atelier-seance-avancee-de-preparation-mentale-3-4-heures" tabindex="-1">Atelier : Séance avancée de préparation mentale (3-4 heures) <a class="header-anchor" href="#atelier-seance-avancee-de-preparation-mentale-3-4-heures" aria-label="Permalink to &quot;Atelier : Séance avancée de préparation mentale (3-4 heures)&quot;">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h2><p>Cet atelier est une session théorique avancée de 3 à 4 heures destinée à 6 à 8 joueurs d&#39;élite. Axée sur un travail psychologique approfondi et un apprentissage basé sur la vulnérabilité, elle va au-delà des compétences mentales de base pour explorer le jeu intérieur à un niveau profond.</p><div class="tip custom-block"><p class="custom-block-title">Ce guide comporte deux sections.</p><ul><li><strong><a href="#for-participants">Pour les participants</a></strong> - Ce que les joueurs vivront et apprendront</li><li><strong><a href="#for-facilitators">Pour les animateurs</a></strong> - Comment animer l&#39;atelier en tant que coordinateur de la performance mentale</li></ul></div><p><strong>Différence par rapport à la séance pour débutants :</strong></p><ul><li><strong>Débutant (2-3 h) :</strong> Introduction aux concepts du jeu mental → <a href="/en/mental-journey/session-guide">Voir le guide du parcours mental</a></li><li><strong>Niveau avancé (3-4 h) :</strong> Travail psychologique approfondi avec exercices de vulnérabilité (cette page)</li></ul><h2 id="acces-rapide" tabindex="-1">Accès rapide <a class="header-anchor" href="#acces-rapide" aria-label="Permalink to &quot;Accès rapide&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>But</th><th>Accéder</th></tr></thead><tbody><tr><td><strong>Pour les participants</strong></td><td>À quoi s&#39;attendre et comment se préparer</td><td><a href="#pour-participants">Voir la section</a></td></tr><tr><td><strong>À l&#39;attention des animateurs</strong></td><td>Guide complet de la séance et exercices</td><td><a href="#pour-animateurs">Voir la section</a></td></tr><tr><td><strong>Matériel de la session</strong></td><td>Exercices et feuilles de travail</td><td><a href="#facilitator-materials">Voir les ressources</a></td></tr><tr><td><strong>Guides associés</strong></td><td>Autres formats de formation</td><td><a href="/en/mental-journey/">Voyage mental</a> • <a href="/en/training-camp">Camp d&#39;entraînement</a></td></tr></tbody></table><hr><h2 id="pour-les-participants" tabindex="-1">Pour les participants <a class="header-anchor" href="#pour-les-participants" aria-label="Permalink to &quot;Pour les participants&quot;">​</a></h2><h3 id="a-quoi-s-39-attendre" tabindex="-1">À quoi s&#39;attendre <a class="header-anchor" href="#a-quoi-s-39-attendre" aria-label="Permalink to &quot;À quoi s&amp;#39;attendre&quot;">​</a></h3><p>Il ne s&#39;agit pas d&#39;une séance d&#39;entraînement classique. Vous participerez à des discussions approfondies sur les aspects mentaux et émotionnels de la pétanque, rarement abordés ouvertement.</p><p><strong>Cet atelier est :</strong></p><ul><li>✅ Un espace sûr pour explorer ses pensées et ses peurs intérieures</li><li>✅ Apprentissage basé sur la vulnérabilité avec les coéquipiers</li><li>✅ Relier les schémas mentaux à la performance</li><li>✅ Développer l&#39;intelligence psychologique de l&#39;équipe</li></ul><p><strong>Cet atelier n&#39;est PAS :</strong></p><ul><li>❌ Entraînement technique ou tactique</li><li>❌ Thérapie ou consultation</li><li>❌ Discours de pensée positive ou de motivation</li><li>❌ Jugement ou critique</li></ul><h3 id="structure-de-la-session" tabindex="-1">Structure de la session <a class="header-anchor" href="#structure-de-la-session" aria-label="Permalink to &quot;Structure de la session&quot;">​</a></h3>',17)),(a(),s(u,null,{default:n(()=>[l(g,{id:"mermaid-165",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BAtelier%5D%20--%3E%20B%5BFondation%2060%20min%5D%0A%20%20%20%20B%20--%3E%20C%5BTravail%20en%20profondeur%2090%20min%5D%0A%20%20%20%20C%20--%3E%20D%5BInt%C3%A9gration%2045%20min%5D%0A%20%20%20%20D%20--%3E%20E%5BFermeture%20dans%2015%20minutes%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23ffe4e1%0A%20%20%20%20style%20D%20fill%3A%23e3f2fd%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:n(()=>[...c[0]||(c[0]=[o(" Loading... ",-1)])]),_:1})),c[5]||(c[5]=r('<p><strong>Durée totale :</strong> 3 à 4 heures <strong>Taille du groupe :</strong> 6 à 8 joueurs <strong>Format :</strong> Discussion en cercle avec exercices structurés</p><h3 id="ce-que-vous-apprendrez" tabindex="-1">Ce que vous apprendrez <a class="header-anchor" href="#ce-que-vous-apprendrez" aria-label="Permalink to &quot;Ce que vous apprendrez&quot;">​</a></h3><h4 id="phase-1-fondations-60-min" tabindex="-1">Phase 1 : Fondations (60 min) <a class="header-anchor" href="#phase-1-fondations-60-min" aria-label="Permalink to &quot;Phase 1 : Fondations (60 min)&quot;">​</a></h4><ul><li>Règles de base pour la sécurité psychologique</li><li>La « Matrice d&#39;enregistrement » - reconnaissance de votre état actuel</li><li>L&#39;« iceberg de la pétanque » - explorer les pensées cachées</li></ul><h4 id="phase-2-travail-en-profondeur-90-min" tabindex="-1">Phase 2 : Travail en profondeur (90 min) <a class="header-anchor" href="#phase-2-travail-en-profondeur-90-min" aria-label="Permalink to &quot;Phase 2 : Travail en profondeur (90 min)&quot;">​</a></h4><ul><li>Créer votre « manuel d&#39;utilisation » pour vos coéquipiers</li><li>Lier les schémas mentaux à la performance</li><li>« La peur dans un chapeau » - briser l&#39;isolement grâce à la vulnérabilité partagée</li></ul><h4 id="phase-3-integration-45-min" tabindex="-1">Phase 3 : Intégration (45 min) <a class="header-anchor" href="#phase-3-integration-45-min" aria-label="Permalink to &quot;Phase 3 : Intégration (45 min)&quot;">​</a></h4><ul><li>Transformer son critique intérieur en coach intérieur</li><li>Création de protocoles d&#39;équipe pour la compétition</li><li>Points clés à retenir pour la piste</li></ul><h4 id="phase-4-cloture-15-min" tabindex="-1">Phase 4 : Clôture (15 min) <a class="header-anchor" href="#phase-4-cloture-15-min" aria-label="Permalink to &quot;Phase 4 : Clôture (15 min)&quot;">​</a></h4><ul><li>Réflexion et engagement</li><li>Suivi et soutien</li></ul><h3 id="regles-de-base" tabindex="-1">Règles de base <a class="header-anchor" href="#regles-de-base" aria-label="Permalink to &quot;Règles de base&quot;">​</a></h3><p>Avant le début de la séance, tous les participants acceptent de :</p><div class="tip custom-block"><p class="custom-block-title">Le conteneur - Règles de base essentielles</p><ol><li><strong>Confidentialité</strong> - Ce qui est dit ici reste ici.</li><li><strong>La règle de Vegas</strong> - Les leçons quittent la salle, les histoires restent</li><li><strong>Interdiction de réparer</strong> - Observez et comprenez, n&#39;essayez pas de résoudre</li><li><strong>Droit de passage</strong> - La vulnérabilité ne peut être imposée</li><li><strong>Respectez le processus</strong> - Faites confiance à l&#39;inconfort.</li></ol></div><h3 id="que-faut-il-apporter" tabindex="-1">Que faut-il apporter ? <a class="header-anchor" href="#que-faut-il-apporter" aria-label="Permalink to &quot;Que faut-il apporter ?&quot;">​</a></h3><p><strong>Requis:</strong></p><ul><li>Esprit ouvert et volonté de partager</li><li>Vos propres expériences et défis</li><li>Respect de la vulnérabilité d&#39;autrui</li></ul><p><strong>Facultatif:</strong></p><ul><li>Carnet de notes pour réflexions personnelles</li><li>Questions sur des difficultés mentales spécifiques</li></ul><h3 id="principales-activites-que-vous-decouvrirez" tabindex="-1">Principales activités que vous découvrirez <a class="header-anchor" href="#principales-activites-que-vous-decouvrirez" aria-label="Permalink to &quot;Principales activités que vous découvrirez&quot;">​</a></h3><h4 id="la-matrice-d-39-enregistrement" tabindex="-1">La matrice d&#39;enregistrement <a class="header-anchor" href="#la-matrice-d-39-enregistrement" aria-label="Permalink to &quot;La matrice d&amp;#39;enregistrement&quot;">​</a></h4><p>Positionnez-vous sur une grille d&#39;énergie et d&#39;humeur. Acceptez que nous ayons tous des états différents.</p><h4 id="l-39-iceberg-de-la-petanque" tabindex="-1">L&#39;iceberg de la pétanque <a class="header-anchor" href="#l-39-iceberg-de-la-petanque" aria-label="Permalink to &quot;L&amp;#39;iceberg de la pétanque&quot;">​</a></h4><p>Explorez ce qui se passe sous la surface – les pensées et les peurs que personne ne voit.</p><h4 id="le-manuel-d-39-utilisation" tabindex="-1">Le manuel d&#39;utilisation <a class="header-anchor" href="#le-manuel-d-39-utilisation" aria-label="Permalink to &quot;Le manuel d&amp;#39;utilisation&quot;">​</a></h4><p>Créez un mode d&#39;emploi pour vous-même afin que vos coéquipiers comprennent comment vous soutenir.</p><h4 id="la-peur-dans-un-chapeau" tabindex="-1">La peur dans un chapeau <a class="header-anchor" href="#la-peur-dans-un-chapeau" aria-label="Permalink to &quot;La peur dans un chapeau&quot;">​</a></h4><p>Partagez anonymement vos peurs les plus profondes et entendez-les validées par vos pairs. Brisez l&#39;isolement.</p><h4 id="recadrage-de-la-critique-interieure" tabindex="-1">Recadrage de la critique intérieure <a class="header-anchor" href="#recadrage-de-la-critique-interieure" aria-label="Permalink to &quot;Recadrage de la critique intérieure&quot;">​</a></h4><p>Transformez les pensées négatives envers vous-même en un langage de coaching constructif.</p><h3 id="apres-l-39-atelier" tabindex="-1">Après l&#39;atelier <a class="header-anchor" href="#apres-l-39-atelier" aria-label="Permalink to &quot;Après l&amp;#39;atelier&quot;">​</a></h3><p>Vous repartirez avec :</p><ul><li>Une compréhension plus approfondie de vos schémas mentaux</li><li>Protocoles d&#39;équipe pour s&#39;entraider</li><li>Phrases reformulées du coach intérieur</li><li>Lien avec ses coéquipiers grâce à la vulnérabilité partagée</li><li>Outils concrets pour la concurrence</li></ul><div class="warning custom-block"><p class="custom-block-title">Gueule de bois de la vulnérabilité</p><p>Après un partage aussi intense, il est possible que vous vous sentiez vulnérable ou que vous éprouviez des regrets. C&#39;est tout à fait normal. L&#39;animateur prendra de vos nouvelles dans les 24 heures. N&#39;oubliez pas : votre témoignage a été bénéfique à tous.</p></div><hr><h2 id="pour-les-animateurs" tabindex="-1">Pour les animateurs <a class="header-anchor" href="#pour-les-animateurs" aria-label="Permalink to &quot;Pour les animateurs&quot;">​</a></h2><h3 id="votre-role-en-tant-que-coordinateur-de-la-performance-mentale" tabindex="-1">Votre rôle en tant que coordinateur de la performance mentale <a class="header-anchor" href="#votre-role-en-tant-que-coordinateur-de-la-performance-mentale" aria-label="Permalink to &quot;Votre rôle en tant que coordinateur de la performance mentale&quot;">​</a></h3><p>En tant que <strong>coordinateur de la performance mentale (MPC)</strong>, vous facilitez des discussions approfondies sur le jeu mental, créant une sécurité psychologique qui se traduit par une performance sur la piste.</p><div class="warning custom-block"><p class="custom-block-title">Concept critique</p><p><strong>Vous n&#39;êtes ni un coach technique ni un thérapeute.</strong> Votre rôle est de faciliter un apprentissage basé sur la vulnérabilité qui aide les joueurs à comprendre le lien entre leurs pensées intérieures et leurs performances.</p></div><h3 id="vos-responsabilites" tabindex="-1">Vos responsabilités <a class="header-anchor" href="#vos-responsabilites" aria-label="Permalink to &quot;Vos responsabilités&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Principales responsabilités</p><ul><li><strong>Facilitez, ne faites pas la leçon</strong> - Vous guidez la discussion, vous n&#39;enseignez pas de technique</li><li><strong>Créer un espace sûr</strong> - Instaurer et maintenir un climat de confiance psychologique</li><li><strong>Passer de la théorie à la pratique</strong> - Relier le contenu du site web à l&#39;expérience intérieure</li><li><strong>Surveillez la dynamique du groupe</strong> - Observez qui est impliqué, qui est réticent</li><li><strong>Respecter les limites</strong> - Savoir quand faire appel à un professionnel</li></ul></div><h3 id="preparation-avant-l-39-atelier" tabindex="-1">Préparation avant l&#39;atelier <a class="header-anchor" href="#preparation-avant-l-39-atelier" aria-label="Permalink to &quot;Préparation avant l&amp;#39;atelier&quot;">​</a></h3><h3 id="competences-essentielles" tabindex="-1">Compétences essentielles <a class="header-anchor" href="#competences-essentielles" aria-label="Permalink to &quot;Compétences essentielles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Compétence</th><th>Ce que cela signifie</th><th>Comment développer</th></tr></thead><tbody><tr><td><strong>Intelligence émotionnelle</strong></td><td>Détecter les micro-expressions d&#39;inconfort</td><td>Pratiquer l&#39;observation active</td></tr><tr><td><strong>Autorité neutre</strong></td><td>Inspirer le respect sans pouvoir technique</td><td>Établir sa crédibilité par la présence</td></tr><tr><td><strong>Contexte sportif</strong></td><td>Comprendre les mécanismes de pression</td><td>Apprenez le vocabulaire et la culture de la pétanque.</td></tr><tr><td><strong>Aïkido verbal</strong></td><td>Rejoignez la résistance, ne la combattez pas.</td><td>Pratiquez une communication non défensive</td></tr></tbody></table><details class="details custom-block"><summary>Termes clés de la pétanque à connaître</summary><ul><li><strong>Carré</strong> - Coup parfait qui déplace la boule adverse</li><li><strong>Bibber</strong> - Le « yips » - tremblement involontaire lors de la libération</li><li><strong>Donnée</strong> - Le « donné » - accepter le terrain tel qu&#39;il est</li><li><strong>Portée</strong> - Lancer sans rebond</li><li><strong>Roulette</strong> - Tir roulant</li><li><strong>Cochonnet</strong> - La boule cible (cochon)</li></ul></details><h2 id="configuration-physique-le-cercle-magique" tabindex="-1">Configuration physique : Le cercle magique <a class="header-anchor" href="#configuration-physique-le-cercle-magique" aria-label="Permalink to &quot;Configuration physique : Le cercle magique&quot;">​</a></h2><h3 id="exigences-relatives-a-l-39-emplacement" tabindex="-1">Exigences relatives à l&#39;emplacement <a class="header-anchor" href="#exigences-relatives-a-l-39-emplacement" aria-label="Permalink to &quot;Exigences relatives à l&amp;#39;emplacement&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Configuration critique</p><p><strong>Choisissez un espace neutre, loin des pistes.</strong> Cela marque un passage de l&#39;effort physique à l&#39;effort mental.</p><p>Exigences:</p><ul><li>✅ Insonorisé ou privé</li><li>✅ Température confortable</li><li>✅ Aucune distraction (téléphones éteints)</li><li>✅ Lumière naturelle si possible</li><li>✅ Séparé de la zone d&#39;entraînement</li></ul></div><h3 id="la-configuration-du-cercle" tabindex="-1">La configuration du cercle <a class="header-anchor" href="#la-configuration-du-cercle" aria-label="Permalink to &quot;La configuration du cercle&quot;">​</a></h3><p><strong>Sièges:</strong></p><ul><li>Cercle parfait de chaises</li><li><strong>PAS DE TABLES</strong> - Les tables créent des barrières et masquent le langage corporel.</li><li>Toutes les chaises sont à la même hauteur (pas de positions électriques).</li><li>Le coordinateur est assis au sein du cercle (et non devant).</li></ul><p><strong>Artefacts du centre :</strong></p><ul><li>Placer les boules et le cochonnet au centre</li><li>Ancre le travail dans le sport</li><li>Rappel visuel d&#39;un objectif commun</li></ul>',52)),(a(),s(u,null,{default:n(()=>[l(g,{id:"mermaid-628",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BEspace%20physique%5D%20--%3E%20B%5BSignes%20de%20changement%20mental%5D%0A%20%20%20%20A%20--%3E%20C%5BPas%20de%20barri%C3%A8res%5D%0A%20%20%20%20A%20--%3E%20D%5B%C3%89galit%C3%A9%20des%20chances%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BS%C3%A9curit%C3%A9%20psychologique%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:n(()=>[...c[1]||(c[1]=[o(" Loading... ",-1)])]),_:1})),c[6]||(c[6]=r('<h2 id="structure-de-la-seance-3-4-heures" tabindex="-1">Structure de la séance (3-4 heures) <a class="header-anchor" href="#structure-de-la-seance-3-4-heures" aria-label="Permalink to &quot;Structure de la séance (3-4 heures)&quot;">​</a></h2><h3 id="phase-1-fondations-60-minutes" tabindex="-1">Phase 1 : Fondations (60 minutes) <a class="header-anchor" href="#phase-1-fondations-60-minutes" aria-label="Permalink to &quot;Phase 1 : Fondations (60 minutes)&quot;">​</a></h3><h4 id="_1-accueil-et-regles-de-base-15-min" tabindex="-1">1. Accueil et règles de base (15 min) <a class="header-anchor" href="#_1-accueil-et-regles-de-base-15-min" aria-label="Permalink to &quot;1. Accueil et règles de base (15 min)&quot;">​</a></h4><p><strong>Le contrat social :</strong></p><div class="tip custom-block"><p class="custom-block-title">Le conteneur - Règles de base essentielles</p><p>Avant tout partage, le groupe DOIT s&#39;entendre sur les points suivants :</p><ol><li><strong>Confidentialité</strong> - Ce qui est dit ici reste ici.</li><li><strong>La règle de Vegas</strong> - Les leçons quittent la salle, les histoires restent</li><li><strong>Interdiction de réparer</strong> - Observez et comprenez, n&#39;essayez pas de résoudre</li><li><strong>Droit de passage</strong> - La vulnérabilité ne peut être imposée</li><li><strong>Respectez le processus</strong> - Faites confiance à l&#39;inconfort.</li></ol></div><p><strong>Votre script :</strong></p><blockquote><p>« Bienvenue. Cet espace est différent de la piste. Ici, nous explorons ce qui se passe <em>à l&#39;intérieur</em> lorsque vous vous apprêtez à prendre cette photo. Tout ce qui est partagé ici est confidentiel. Les leçons apprises peuvent partir, mais les histoires personnelles restent. Vous n&#39;êtes pas là pour vous corriger les uns les autres, mais simplement pour comprendre. Et vous pouvez toujours passer votre tour. Êtes-vous tous d&#39;accord ? »</p></blockquote><h4 id="_2-activite-la-matrice-de-pointage-20-min" tabindex="-1">2. Activité : La matrice de pointage (20 min) <a class="header-anchor" href="#_2-activite-la-matrice-de-pointage-20-min" aria-label="Permalink to &quot;2. Activité : La matrice de pointage (20 min)&quot;">​</a></h4><p><strong>Objectif :</strong> Normaliser le fait d&#39;admettre sa fatigue ou son stress</p><p><strong>Matériel :</strong> Tableau blanc ou paperboard, post-it</p><p><strong>Procédure:</strong></p><ol><li>Dessinez une matrice 2x2 : Énergie élevée/faible (verticale), Positif/Négatif (horizontal)</li><li>Chaque joueur écrit son nom sur un post-it.</li><li>Placer la note dans leur quadrant actuel</li><li>Discussion : « Nous avons trois personnes en état de « faible énergie/négatif ». Quel impact cela a-t-il sur notre séance d&#39;aujourd&#39;hui ? »</li></ol>',12)),(a(),s(u,null,{default:n(()=>[l(g,{id:"mermaid-715",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BMatrice%20d%26%2339%3Benregistrement%5D%20--%3E%20B%5B%C3%89nergie%20%C3%A9lev%C3%A9e%20%2B%20Positive%5D%0A%20%20%20%20A%20--%3E%20C%5B%C3%89nergie%20%C3%A9lev%C3%A9e%20%2B%20N%C3%A9gative%5D%0A%20%20%20%20A%20--%3E%20D%5BFaible%20%C3%A9nergie%20%2B%20Positive%5D%0A%20%20%20%20A%20--%3E%20E%5BFaible%20%C3%A9nergie%20%2B%20N%C3%A9gatif%5D%0A%0A%20%20%20%20B%20--%3E%20F%5BReconna%C3%AEtre%20tous%20les%20%C3%89tats%5D%0A%20%20%20%20C%20--%3E%20F%0A%20%20%20%20D%20--%3E%20F%0A%20%20%20%20E%20--%3E%20F%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:n(()=>[...c[2]||(c[2]=[o(" Loading... ",-1)])]),_:1})),c[7]||(c[7]=r('<p><strong>Conseils pour l&#39;animation :</strong></p><ul><li>Ne considérez aucun quadrant comme « mauvais ».</li><li>Demandez-vous : « De quoi votre corps a-t-il besoin en ce moment ? »</li><li>Observez les schémas : « Vous êtes trois au même endroit – qu&#39;est-ce que cela signifie ? »</li></ul><h4 id="_3-activite-l-39-iceberg-de-la-petanque-25-min" tabindex="-1">3. Activité : L&#39;iceberg de la pétanque (25 min) <a class="header-anchor" href="#_3-activite-l-39-iceberg-de-la-petanque-25-min" aria-label="Permalink to &quot;3. Activité : L&amp;#39;iceberg de la pétanque (25 min)&quot;">​</a></h4><p><strong>Objectif :</strong> Visualiser les pensées intérieures cachées</p><p><strong>Matériel :</strong> Grande feuille de papier, marqueurs</p><p><strong>Procédure:</strong></p><ol><li>Dessinez un iceberg sur une feuille de papier.</li><li><strong>Hors de l&#39;eau :</strong> Écrivez « Technique, Le lancer, Le résultat »</li><li><strong>Sous l&#39;eau :</strong> Demandez : « Que se passe-t-il dans votre esprit que personne ne voit ? »</li></ol><p><strong>Invites :</strong></p><ul><li>« De quoi as-tu peur quand tu t’avances pour tirer ? »</li><li>« Quel jugement vous inquiète ? »</li><li>«Que dit votre voix intérieure lorsque vous ratez votre coup?»</li></ul><p><strong>La question essentielle :</strong></p><blockquote><p>«Que se passe-t-il pour votre bras lanceur lorsque les éléments &quot;sous-marins&quot; deviennent trop lourds?&quot; »</p></blockquote><p>Cela relie la charge mentale à la tension physique (le bibber/yips).</p><details class="details custom-block"><summary>Réponses courantes « Sous l&#39;eau »</summary><ul><li>La peur de décevoir l&#39;équipe</li><li>Inquiétez-vous d&#39;avoir l&#39;air stupide.</li><li>Doute sur les capacités</li><li>Comparaison avec d&#39;autres</li><li>Pression pour prouver sa valeur</li><li>Peur du jugement de l&#39;entraîneur/des coéquipiers</li><li>Syndrome de l&#39;imposteur</li></ul></details><h3 id="phase-2-travail-en-profondeur-90-minutes" tabindex="-1">Phase 2 : Travail en profondeur (90 minutes) <a class="header-anchor" href="#phase-2-travail-en-profondeur-90-minutes" aria-label="Permalink to &quot;Phase 2 : Travail en profondeur (90 minutes)&quot;">​</a></h3><h4 id="_4-activite-le-manuel-d-39-utilisation-30-min" tabindex="-1">4. Activité : Le manuel d&#39;utilisation (30 min) <a class="header-anchor" href="#_4-activite-le-manuel-d-39-utilisation-30-min" aria-label="Permalink to &quot;4. Activité : Le manuel d&amp;#39;utilisation (30 min)&quot;">​</a></h4><p><strong>Objectif :</strong> Mettre en œuvre l&#39;empathie – aider les membres de l&#39;équipe à se comprendre.</p><p><strong>Matériel :</strong> Feuilles de travail (une par joueur)</p><p><strong>Modèle de manuel d&#39;utilisation :</strong></p><table tabindex="0"><thead><tr><th>Section</th><th>Rapide</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Ma signature de stress</strong></td><td>«Quand je suis anxieux, je... »</td><td>&quot;...devenir complètement silencieux&quot;</td></tr><tr><td><strong>Comment me gérer</strong></td><td>«Quand je rate un tir crucial, j&#39;ai besoin de...»</td><td>&quot;...le silence, pas les encouragements&quot;</td></tr><tr><td><strong>Mes pensées intérieures</strong></td><td>«Le mensonge que je me raconte est...»</td><td>« …que je ne suis pas assez bon »</td></tr><tr><td><strong>Mon déclencheur</strong></td><td>«Je me mets sur la défensive quand...»</td><td>&quot;...quelqu&#39;un remet en question mon choix de tir&quot;</td></tr></tbody></table><p><strong>Procédure:</strong></p><ol><li>Donnez aux joueurs 10 minutes pour terminer en silence</li><li>Faites le tour du cercle - chaque personne partage UNE section</li><li>D&#39;autres peuvent poser des questions de clarification (et non des conseils !).</li><li>Le coordinateur valide chaque action</li></ol><p><strong>Script d&#39;animation :</strong></p><blockquote><p>« Voici votre mode d&#39;emploi. Si vos coéquipiers savent que vous vous taisez lorsque vous êtes anxieux, ils ne le prendront pas mal. S&#39;ils savent que vous avez besoin de silence après un échec, ils n&#39;essaieront pas de vous « réparer ». C&#39;est ainsi que nous développons l&#39;intelligence collective. »</p></blockquote><h4 id="_5-relier-le-contenu-du-site-web-a-la-pensee-interieure-30-min" tabindex="-1">5. Relier le contenu du site web à la pensée intérieure (30 min) <a class="header-anchor" href="#_5-relier-le-contenu-du-site-web-a-la-pensee-interieure-30-min" aria-label="Permalink to &quot;5. Relier le contenu du site web à la pensée intérieure (30 min)&quot;">​</a></h4><p><strong>Objectif :</strong> Faire le lien entre le contenu technique et l’expérience psychologique</p><p>Choisissez 2 à 3 sections sur le site web de l&#39;Académie et explorez le jeu intérieur :</p><p><strong>Exemple 1 : Technique – La prise et le relâchement</strong></p><p><strong>La question de la confiance :</strong></p><blockquote><p>« Quand vous êtes à 12-12 dans un tournoi, est-ce que votre main <em>ressemble</em> à la description technique ? Est-ce que ce sont les muscles qui changent ou la pensée « Ne la laisse pas tomber » qui modifie votre prise ? »</p></blockquote><p><strong>Le micro-tremblement :</strong></p><blockquote><p>« Qui ici ressent ce &quot;micro-frémissement&quot; d&#39;anxiété ? Quelle pensée intérieure le déclenche ? »</p></blockquote><p><strong>Exemple 2 : Tactiques – Pointer vs. Tirer</strong></p><p><strong>Profil de risque :</strong></p><blockquote><p>« Lorsque le guide dit « Tirez pour gagner », votre réaction est-elle l’excitation ou la crainte ? Qu’est-ce que cela vous révèle sur votre rapport au risque ? »</p></blockquote><p><strong>L&#39;imposteur :</strong></p><blockquote><p>« Vous arrive-t-il de viser alors que vous <em>savez</em> que vous devriez tirer, juste pour éviter la honte de rater votre cible ? Quel est le prix de cette sécurité ? »</p></blockquote><p><strong>Exemple 3 : Nutrition – Jour de compétition</strong></p><p><strong>Le piège des aliments réconfortants :</strong></p><blockquote><p>« Mangez-vous ce dont votre corps a besoin ou ce que votre anxiété réclame ? Comment faire la différence ? »</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Technique de facilitation</p><p>Ne faites pas la leçon sur le contenu. Posez des questions qui relient les informations techniques à leur expérience vécue. La compréhension vient d&#39;EUX, pas de vous.</p></div><h4 id="_6-activite-la-peur-dans-un-chapeau-30-min" tabindex="-1">6. Activité : La peur dans un chapeau (30 min) <a class="header-anchor" href="#_6-activite-la-peur-dans-un-chapeau-30-min" aria-label="Permalink to &quot;6. Activité : La peur dans un chapeau (30 min)&quot;">​</a></h4><p><strong>Objectif :</strong> Rompre le cercle vicieux de l&#39;isolement – montrer que les pairs partagent de profondes insécurités</p><p><strong>Matériel :</strong> Papier, stylo, chapeau/sac</p><p><strong>Procédure:</strong></p><ol><li>Chacun écrit anonymement une peur profonde concernant sa carrière ou son équipe</li><li>Pliez les papiers et mélangez-les dans le chapeau</li><li>Chaque joueur tire une note (qui n&#39;est pas la sienne).</li><li>Lisez-le à voix haute</li><li>Validez-le : « Je peux comprendre pourquoi quelqu&#39;un ressentirait cela parce que… »</li></ol><p><strong>Exemples de peurs :</strong></p><ul><li>« J’ai bien peur d’avoir atteint mon apogée et de ne jamais m’améliorer. »</li><li>« J&#39;ai peur que mes coéquipiers pensent que je suis surcoté. »</li><li>« J&#39;ai peur de craquer au moment crucial. »</li><li>« J&#39;ai peur d&#39;être remplacé par des joueurs plus jeunes. »</li></ul><p><strong>Le pouvoir :</strong> Lorsque les joueurs entendent leur peur secrète lue à voix haute et validée par leurs pairs, la honte disparaît. Ils réalisent : « Je ne suis pas seul. C&#39;est normal. »</p><p><strong>Rôle du coordonnateur :</strong></p><ul><li>Reconnaissez CHAQUE peur comme légitime</li><li>Ne minimisez pas : dire « Ce n&#39;est pas vrai ! » invalide le sentiment.</li><li>Demandez : « Combien d&#39;entre vous ont déjà ressenti quelque chose de similaire ? »</li></ul>',50)),(a(),s(u,null,{default:n(()=>[l(g,{id:"mermaid-1094",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BLa%20peur%20dans%20un%20chapeau%5D%20--%3E%20B%5BPartage%20anonyme%5D%0A%20%20%20%20B%20--%3E%20C%5BValidation%20par%20les%20pairs%5D%0A%20%20%20%20C%20--%3E%20D%5BLa%20honte%20se%20dissout%5D%0A%20%20%20%20D%20--%3E%20E%5BPauses%20d%26%2339%3Bisolement%5D%0A%20%20%20%20E%20--%3E%20F%5BS%C3%A9curit%C3%A9%20psychologique%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffe4e1%0A%20%20%20%20style%20F%20fill%3A%23e8f5e9%0A"})]),fallback:n(()=>[...c[3]||(c[3]=[o(" Loading... ",-1)])]),_:1})),c[8]||(c[8]=r('<h3 id="phase-3-integration-45-minutes" tabindex="-1">Phase 3 : Intégration (45 minutes) <a class="header-anchor" href="#phase-3-integration-45-minutes" aria-label="Permalink to &quot;Phase 3 : Intégration (45 minutes)&quot;">​</a></h3><h4 id="_7-activite-recadrer-le-critique-interieur-25-min" tabindex="-1">7. Activité : Recadrer le critique intérieur (25 min) <a class="header-anchor" href="#_7-activite-recadrer-le-critique-interieur-25-min" aria-label="Permalink to &quot;7. Activité : Recadrer le critique intérieur (25 min)&quot;">​</a></h4><p><strong>Objectif :</strong> Restructuration cognitive – modifier le dialogue interne</p><p><strong>Matériel :</strong> Feuille de travail</p><p><strong>Procédure:</strong></p><p><strong>Étape 1 : Identifier le critique (10 min)</strong></p><blockquote><p>« Notez la phrase EXACTE que votre critique intérieure prononce après un échec. Pas la version polie, mais la version brutale. »</p></blockquote><p>Exemples :</p><ul><li>«Tu t&#39;étouffes toujours.»</li><li>« Tout le monde te regarde échouer »</li><li>« Tu te ridiculises. »</li><li>« Tu n&#39;as rien à faire ici. »</li></ul><p><strong>Étape 2 : Se repositionner comme un coach intérieur (10 min)</strong></p><blockquote><p>« Maintenant, réécrivez cela comme votre coach intérieur : ferme mais encourageant. »</p></blockquote><p>Exemples :</p><ul><li>Critique : « Tu craques toujours » → Coach : « Reprends-toi et respire. Prochain tir. »</li><li>Critique : « Tout le monde te regarde échouer » → Coach : « Concentre-toi sur l&#39;objectif, pas sur la foule »</li><li>Critique : « Tu te ridiculises » → Coach : « Un tir à la fois. Tu as déjà fait ça. »</li></ul><p><strong>Étape 3 : Exercices en binôme (5 min)</strong></p><blockquote><p>« Partagez votre phrase de coach avec un partenaire. Il vous la rappellera lorsqu&#39;il verra le critique apparaître. »</p></blockquote><h4 id="_8-passage-a-la-piste-20-min" tabindex="-1">8. Passage à la piste (20 min) <a class="header-anchor" href="#_8-passage-a-la-piste-20-min" aria-label="Permalink to &quot;8. Passage à la piste (20 min)&quot;">​</a></h4><p><strong>Objectif :</strong> Créer des protocoles opérationnels pour la compétition</p><p><strong>Questions à débattre :</strong></p><ol><li>« Quelle est LA chose que vous avez apprise aujourd&#39;hui et que vous utiliserez lors de votre prochaine compétition ? »</li><li>« Comment vos coéquipiers sauront-ils que vous avez besoin de soutien ? »</li><li>« Quel est votre signal pour dire « J’ai besoin d’une pause mentale » ? »</li></ol><p><strong>Créer des protocoles d&#39;équipe :</strong></p><table tabindex="0"><thead><tr><th>Situation</th><th>Protocole</th><th>Exemple</th></tr></thead><tbody><tr><td><strong>Après un échec</strong></td><td>Consultez le manuel d&#39;utilisation</td><td>« Marc a besoin de silence, Lisa a besoin d&#39;un check. »</td></tr><tr><td><strong>Sentiment de pression</strong></td><td>Utilisez la phrase Coach</td><td>&quot;Réinitialisez et respirez&quot;</td></tr><tr><td><strong>Tensions au sein de l&#39;équipe</strong></td><td>Délai d&#39;attente dépassé</td><td>&quot;Prenons 2 minutes&quot;</td></tr><tr><td><strong>La voix intérieure critique est forte</strong></td><td>Réinitialisation physique</td><td>Toucher les boules, respirer profondément</td></tr></tbody></table><h3 id="phase-4-cloture-15-minutes" tabindex="-1">Phase 4 : Clôture (15 minutes) <a class="header-anchor" href="#phase-4-cloture-15-minutes" aria-label="Permalink to &quot;Phase 4 : Clôture (15 minutes)&quot;">​</a></h3><h4 id="_9-le-depart-10-min" tabindex="-1">9. Le départ (10 min) <a class="header-anchor" href="#_9-le-depart-10-min" aria-label="Permalink to &quot;9. Le départ (10 min)&quot;">​</a></h4><p><strong>Procédure:</strong> On fait le tour du cercle, chacun partage :</p><ol><li><strong>Ce que vous emportez :</strong> « Quel savoir ou outil retirez-vous de votre expérience ? »</li><li><strong>Ce que vous laissez derrière vous :</strong> « À quoi renoncez-vous ? »</li></ol><p><strong>Rôle du coordonnateur :</strong></p><ul><li>Remercier chaque personne pour sa contribution</li><li>Valider le travail effectué</li><li>Rappel de la confidentialité</li></ul><h4 id="_10-protocole-de-suivi-5-min" tabindex="-1">10. Protocole de suivi (5 min) <a class="header-anchor" href="#_10-protocole-de-suivi-5-min" aria-label="Permalink to &quot;10. Protocole de suivi (5 min)&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Essentiel : Prévenir les séquelles de la vulnérabilité</p><p>Le travail en profondeur engendre une « gueule de bois de vulnérabilité » – des regrets ou de la honte à l&#39;idée de partager.</p><p><strong>Votre protocole sur 24 heures :</strong></p><ul><li>Envoyez un SMS à toute personne ayant beaucoup partagé au cours des dernières 24 heures.</li><li>Message : « Merci pour votre courage d&#39;hier. Ce que vous avez partagé a été utile à tous. »</li><li>Questionnaire : « Comment vous sentez-vous par rapport à la séance ? »</li></ul></div><p><strong>Conclusion :</strong></p><blockquote><p>« Ce qui s&#39;est passé aujourd&#39;hui a demandé du courage. Vous étiez présents, vous vous êtes ouverts, vous avez fait confiance au processus. C&#39;est ce même courage que vous apporterez sur les pistes. N&#39;oubliez pas : les leçons quittent cette salle, mais les histoires restent. Merci. »</p></blockquote><h2 id="resistance-a-la-manutention" tabindex="-1">Résistance à la manutention <a class="header-anchor" href="#resistance-a-la-manutention" aria-label="Permalink to &quot;Résistance à la manutention&quot;">​</a></h2><h3 id="l-39-athlete-«-trop-cool-»" tabindex="-1">L&#39;athlète « trop cool » <a class="header-anchor" href="#l-39-athlete-«-trop-cool-»" aria-label="Permalink to &quot;L&amp;#39;athlète « trop cool »&quot;">​</a></h3><p><strong>Scénario :</strong> Un joueur lève les yeux au ciel lors d&#39;un exercice de vulnérabilité</p><p><strong>Stratégie :</strong> Aïkido verbal (Alignement et pivotement)</p><p><strong>Scénario:</strong></p><blockquote><p>« Je vois bien ta réaction, [Nom]. Franchement, je comprends. Parler de ses sentiments, ça fait un peu facile. Mais la piste est inconfortable. Si on n&#39;arrive pas à supporter l&#39;inconfort de cette pièce, on ne s&#39;entraîne pas assez pour affronter l&#39;inconfort du jeu. Tu peux me faire confiance pendant 20 minutes ? »</p></blockquote><h3 id="le-participant-silencieux" tabindex="-1">Le participant silencieux <a class="header-anchor" href="#le-participant-silencieux" aria-label="Permalink to &quot;Le participant silencieux&quot;">​</a></h3><p><strong>Scénario :</strong> Une personne n&#39;a pas parlé depuis 45 minutes.</p><p><strong>Stratégie :</strong> Créer un point d&#39;entrée à faible risque</p><p><strong>Scénario:</strong></p><blockquote><p>« [Nom], je remarque que tu assimiles tout cela. Qu&#39;est-ce qui te marque le plus jusqu&#39;à présent ? Même un seul mot. »</p></blockquote><h3 id="le-la-trop-partageur-euse" tabindex="-1">Le/La trop-partageur/euse <a class="header-anchor" href="#le-la-trop-partageur-euse" aria-label="Permalink to &quot;Le/La trop-partageur/euse&quot;">​</a></h3><p><strong>Scénario :</strong> Une personne domine la conversation avec de longs récits.</p><p><strong>Stratégie :</strong> Redirection en douceur</p><p><strong>Scénario:</strong></p><blockquote><p>« Merci pour ça, [Nom]. Je veux m&#39;assurer que chacun ait de la place. Écoutons quelqu&#39;un qui ne s&#39;est pas encore exprimé. »</p></blockquote><h3 id="le-fixeur" tabindex="-1">Le Fixeur <a class="header-anchor" href="#le-fixeur" aria-label="Permalink to &quot;Le Fixeur&quot;">​</a></h3><p><strong>Scénario :</strong> Une personne essaie de résoudre les problèmes des autres.</p><p><strong>Stratégie :</strong> Renforcer les règles de base</p><p><strong>Scénario:</strong></p><blockquote><p>« J’apprécie votre volonté d’aider, mais n’oubliez pas notre règle : observer et comprendre, ne pas réparer. [Intervenant initial], de quoi avez-vous besoin maintenant ? »</p></blockquote><h2 id="liste-de-verification-des-materiaux" tabindex="-1">Liste de vérification des matériaux <a class="header-anchor" href="#liste-de-verification-des-materiaux" aria-label="Permalink to &quot;Liste de vérification des matériaux&quot;">​</a></h2><details class="details custom-block"><summary>Matériel d&#39;atelier</summary><p><strong>Configuration physique :</strong></p><ul><li>[ ] Chaises (6-8, pas de tables)</li><li>[ ] Boules et cochonnet pour centre</li><li>[ ] tableau à feuilles mobiles ou tableau blanc</li><li>[ ] Marqueurs</li></ul><p><strong>Activités:</strong></p><ul><li>[ ] Notes autocollantes (matrice de pointage)</li><li>[ ] Grande feuille de papier (Activité Iceberg)</li><li>[ ] feuilles de travail du manuel d&#39;utilisation</li><li>[ ] Papier et stylos (La peur dans un chapeau)</li><li>[ ] Fiches de travail sur le critique intérieur/le coach</li></ul><p><strong>Logistique:</strong></p><ul><li>[ ] De l&#39;eau pour les participants</li><li>[ ] Mouchoirs en papier (travail émotionnel !)</li><li>[ ] Minuteur (respecter l&#39;horaire)</li><li>[ ] Liste de contacts des participants (pour le suivi)</li></ul></details><h2 id="coordonnateur-autosoins" tabindex="-1">Coordonnateur Autosoins <a class="header-anchor" href="#coordonnateur-autosoins" aria-label="Permalink to &quot;Coordonnateur Autosoins&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Vous aussi, vous avez besoin de soutien.</p><p>Accueillir la vulnérabilité est exigeant émotionnellement.</p><p><strong>Après l&#39;atelier :</strong></p><ul><li>Faites le point avec un collègue ou un superviseur.</li><li>Notez dans un journal ce qui vous est venu à l&#39;esprit.</li><li>Faites une promenade ou une pause physique.</li><li>Ne ramenez pas leurs histoires à la maison.</li></ul></div><h2 id="mesurer-l-39-impact" tabindex="-1">Mesurer l&#39;impact <a class="header-anchor" href="#mesurer-l-39-impact" aria-label="Permalink to &quot;Mesurer l&amp;#39;impact&quot;">​</a></h2><h3 id="reponse-immediate" tabindex="-1">Réponse immédiate <a class="header-anchor" href="#reponse-immediate" aria-label="Permalink to &quot;Réponse immédiate&quot;">​</a></h3><p>À la fin, demandez :</p><ol><li>« Sur une échelle de 1 à 10, à quel point vous êtes-vous senti(e) en sécurité en partageant aujourd&#39;hui ? »</li><li>« Qu&#39;est-ce qui pourrait améliorer la prochaine séance ? »</li></ol><h3 id="suivi-a-long-terme" tabindex="-1">Suivi à long terme <a class="header-anchor" href="#suivi-a-long-terme" aria-label="Permalink to &quot;Suivi à long terme&quot;">​</a></h3><p>Suivi après 2 à 4 semaines :</p><ul><li>« Avez-vous utilisé des outils de l&#39;atelier ? »</li><li>« Comment votre relation avec votre critique intérieure a-t-elle évolué ? »</li><li>« Qu&#39;est-ce qui est différent dans votre état d&#39;esprit compétitif ? »</li></ul><h2 id="prochaines-etapes" tabindex="-1">Prochaines étapes <a class="header-anchor" href="#prochaines-etapes" aria-label="Permalink to &quot;Prochaines étapes&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">S&#39;appuyer sur ces fondations</p><p>Cet atelier constitue la phase 1. À prendre en compte :</p><ul><li><strong>Séances de suivi</strong> (en ligne ou en présentiel)</li><li><strong>Intégration sur piste</strong> (voir le guide des séances de formation)</li><li><strong>Protocoles d&#39;équipe</strong> (mise en œuvre des manuels d&#39;utilisation en compétition)</li><li><strong>Suivis individuels</strong> (pour les joueurs qui ont besoin de plus de soutien)</li></ul></div>',65))])}]]);export{c as __pageData,p as default};
